package ring_test

import (
	"testing"

	"github.com/ai-verification/go-ringbuf/internal/ring"
)

func TestNewEmpty(t *testing.T) {
	rb := ring.New(4)
	if rb.Cap() != 4 {
		t.Fatalf("expected Cap=4, got %d", rb.Cap())
	}
	if !rb.IsEmpty() {
		t.Fatal("expected empty ring")
	}
	if rb.IsFull() {
		t.Fatal("expected not full")
	}
}

func TestPushPop(t *testing.T) {
	rb := ring.New(3)
	if err := rb.Push(10); err != nil {
		t.Fatal(err)
	}
	if err := rb.Push(20); err != nil {
		t.Fatal(err)
	}
	v, err := rb.Pop()
	if err != nil || v != 10 {
		t.Fatalf("expected Pop=10, got %d err=%v", v, err)
	}
}

func TestPushFullReturnsError(t *testing.T) {
	rb := ring.New(2)
	rb.Push(1)
	rb.Push(2)
	if err := rb.Push(3); err == nil {
		t.Fatal("expected error when pushing to full ring")
	}
}

func TestPopEmptyReturnsError(t *testing.T) {
	rb := ring.New(2)
	_, err := rb.Pop()
	if err == nil {
		t.Fatal("expected error when popping empty ring")
	}
}

func TestPeekDoesNotConsume(t *testing.T) {
	rb := ring.New(3)
	rb.Push(42)
	v, err := rb.Peek()
	if err != nil || v != 42 {
		t.Fatalf("expected Peek=42, got %d err=%v", v, err)
	}
	if rb.Len() != 1 {
		t.Fatalf("Peek consumed item: Len=%d", rb.Len())
	}
}

func TestWrapAround(t *testing.T) {
	rb := ring.New(3)
	rb.Push(1)
	rb.Push(2)
	rb.Push(3)
	rb.Pop()  // removes 1
	rb.Push(4)  // wraps around
	v, _ := rb.Pop()
	if v != 2 {
		t.Fatalf("expected 2 after wrap-around, got %d", v)
	}
	v, _ = rb.Pop()
	if v != 3 {
		t.Fatalf("expected 3, got %d", v)
	}
	v, _ = rb.Pop()
	if v != 4 {
		t.Fatalf("expected 4 after wrap, got %d", v)
	}
}
